# פרק 6 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=6
TITLE='אשם תורם והקטנת הנזק'
SUM=[' <p>שני מנגנונים המפחיתים את חבות המזיק בשל התנהגות הניזוק עצמו.</p> <h3>6.1 אשם תורם — סעיף 68</h3> <p>כאשר ה<strong>ניזוק תרם באשמו</strong> לקרות הנזק (למשל לא חגר חגורה) — הפיצוי מופחת בשיעור היחסי של אחריותו. זהו מנגנון של <strong>חלוקת אחריות</strong>, ולא שלילה מוחלטת (בשונה מהדין הישן). בית המשפט קובע את החלוקה לפי מידת <strong>האשמה המוסרית</strong> והתרומה הסיבתית, באחוזים.</p> <h3>6.2 חובת הקטנת הנזק</h3> <p>על הניזוק לפעול ב<strong>אמצעים סבירים</strong> כדי להקטין את נזקו (טיפול רפואי, חיפוש עבודה חלופית). נזק שניתן היה למנוע בצעדים סבירים — לא ייפסק לזכותו.</p> <h3>6.3 ההבחנה</h3> <p><strong>אשם תורם</strong> מתייחס להתנהגות הניזוק ב<strong>גרימת</strong> הנזק; <strong>הקטנת הנזק</strong> — להתנהגותו <strong>לאחר</strong> שנגרם, בצמצום היקפו.</p> <h3>6.4 נקודות מפתח למבחן</h3> <ul><li>אשם תורם (ס׳ 68) — חלוקת אחריות יחסית, לא שלילה.</li><li>שיעור לפי אשמה מוסרית ותרומה סיבתית.</li><li>אשם תורם (בגרימה) מול הקטנת הנזק (לאחריה).</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 68 לפקודת הנזיקין — אשם תורם", '', 'תרם הניזוק באשמו לנזקו — הפיצוי מופחת בשיעור יחסי לפי חלוקת האחריות בין הצדדים.'), ('חלוקת אחריות', '', 'בית המשפט קובע אחוזי אחריות לפי מידת האשמה המוסרית והתרומה הסיבתית של כל צד.'), ('חובת הקטנת הנזק', '', 'על הניזוק לפעול באמצעים סבירים לצמצום נזקו לאחר האירוע; נזק שניתן היה למנוע סבירות לא ייפסק.'), ('ע״א 316/75 שור נ׳ מדינת ישראל', 'דיון בשאלה כיצד יש לחלק את האחריות בין מזיק לבין ניזוק שנמצא שגם הוא התרשל.', 'נקבע שהמבחן העיקרי לחלוקה הוא מבחן מידת האשמה — העמדת מעשי הרשלנות של שני הצדדים זה מול זה והשוואת משקלם המוסרי. מבחן האדם הסביר משמש מבחן עזר.'), ('ע״א 2061/90 מרצלי נ׳ מדינת ישראל', 'דיון בתביעת נערה בת 14 שנפגעה, ובטענה שיש לייחס לה אשם תורם.', 'לא הוטל אשם תורם על הנערה, משום ש״אדם רך בשנים נעדר שיקול-דעת בשל להערכתם של סיכונים״. הפסק מבטא את הזהירות הרבה של הפסיקה בייחוס אשם תורם לקטינים, אף שאפשר עקרונית.'), ('ע״א 6649/96 הסתדרות מדיצינית הדסה נ׳ גלעד', 'דיון באחריות בית חולים להתאבדות של מטופל, ובטענה שהמטופל עצמו נושא באשם תורם.', 'אין מניעה עקרונית לראות בהתאבדות אשם תורם, וכל מקרה נבחן לגופו. אולם כאשר בית החולים קיבל על עצמו להגן על המטופל מפני עצמו, טענת אשם תורם הייתה מרוקנת את התחייבותו מתוכן — ולכן אינה מתקבלת.'), ('ע״א 5850/10 חברת דפרון בע״מ נ׳ עזבון המנוח י.ג.', 'עובד מת לאחר ששתה במקום עבודתו מתנול בסוברו שזה משקה אלכוהולי; המעסיקה לא נעלה את החומר ולא הזהירה כראוי מפני סכנותיו.', 'ביהמ״ש העליון (השופט רובינשטיין) קבע שהמעסיקה התרשלה ועליה עיקר האחריות, אך ייחס לעובד אשם תורם של 25%: ״אדם מן היישוב יודע כי לשתיית אלכוהול משמעותית השפעה על יכולת העבודה״. הפסק מדגים הפחתה מתונה בתביעת עובד נגד מעסיק.'), ('רע״א 2809/18 קסברי נ׳ רוזן', 'תאונה שבה כל אחד מהצדדים גרם נזק לחברו, ושאלת האחריות בתביעה ובתביעה שכנגד.', 'נקבע שאפשר להפריד בין אחריות צד לנזק של חברו לבין אחריותו לנזקו שלו: התנהגות יכולה להקים אשם תורם בלי להקים אחריות כלפי הצד השני, ורמת הזהירות הנדרשת אינה בהכרח אחידה.'), ('ע״א 252/86 גולדפרב נ׳ כלל חברה לביטוח בע״מ', 'דיון בהיקף הנטל המוטל על ניזוק להקטין את נזקו לאחר התאונה.', 'השופט ברק קבע שאפשר להיעזר ברמת ההתנהגות של דיני הרשלנות, אך רמת ההתנהגות הנדרשת מהמזיק כלפי הניזוק צריכה להיות גבוהה יותר מזו הנדרשת מהניזוק בהקטנת נזקו.'), ('רע״א 4756/16 פלוני נ׳ מדינת ישראל – משטרת ישראל', 'אדם נעצר ללא עילה למעצר לילה, לאחר שסירב לדרישת הקצין הממונה לחתום על תנאי שחרור בערובה שלא היו מוצדקים.', 'השופטת ברק-ארז קבעה ש״הנזק הכרוך במעצרו של המבקש ללא עילה נבע כל כולו מהחלטתו של הקצין הממונה״; העצור לא היה אשם בהחלטה ואף ניסה להניא את הקצין ממנה, ולכן אין לייחס לו אשם תורם. השאלה הנכונה היא אם היה עליו להקטין את הנזק בהסכמה לחתום — הבחנה חדה בין שני המוסדות.')]
QS=[{'q': 'מה התוצאה של אשם תורם לפי ס׳ 68(א)?', 'o': ['הפחתת הפיצויים בשיעור שבית המשפט ימצא לנכון ולצודק לפי מידת אחריות התובע', 'דחיית התביעה כולה', 'העברת האחריות כולה לתובע', 'חלוקת הנזק שווה בשווה בין הצדדים'], 'c': 0, 'e': 'נכון. אשם תורם הוא הגנה יחסית: התביעה עומדת והפיצוי מופחת לפי מידת אחריות התובע.'}, {'q': 'על מי נטל ההוכחה של אשם תורם?', 'o': ['על חברת הביטוח של התובע', 'על התובע, להוכיח שלא התרשל', 'על בית המשפט מיוזמתו', 'על הנתבע הטוען לו'], 'c': 3, 'e': 'נכון. אשם תורם הוא טענת הגנה, והנטל להוכיחה על הנתבע (מלון רמדה שלום נ׳ אמסלם).'}, {'q': 'מהו המבחן העיקרי לחלוקת האחריות בין מזיק לבין ניזוק בעל אשם תורם?', 'o': ['מבחן ״כלל 50%״', 'מבחן התרומה הפיזית בלבד', 'מבחן מידת האשמה — השוואת המשקל המוסרי של מעשי כל צד', 'מבחן היכולת הכלכלית של הצדדים'], 'c': 2, 'e': 'נכון. כך נקבע בע״א 316/75 שור, ומבחן האדם הסביר משמש מבחן עזר.'}, {'q': 'הולך רגל חצה באדום ונפגע מנהג שנסע במהירות מופרזת. בית המשפט קבע שאשמו של הולך הרגל 60% ואשם הנהג 40%. (נניח תביעה לפי פקודת הנזיקין.) מה הדין?', 'o': ['הולך הרגל מקבל 60% מנזקו', 'התביעה נדחית, כי אשם התובע עולה על 50%', 'הולך הרגל מקבל פיצוי מלא', 'הולך הרגל מקבל 40% מנזקו'], 'c': 3, 'e': 'נכון. הפיצוי מופחת בשיעור אשמו (60%), ונותרים 40% מהנזק המלא.'}, {'q': 'מה מחייב ס׳ 68(ב) את בית המשפט לעשות כשהוא מפחית פיצויים בשל אשם תורם?', 'o': ['לנמק בכתב את שיעור ההפחתה בלבד', 'לקבוע ולרשום את סך כל הפיצויים שהתובע היה יכול להיפרע אילולא אשמו', 'להודיע לרשות המסים', 'למנות מומחה לחלוקת האשמה'], 'c': 1, 'e': 'נכון. זו לשון ס׳ 68(ב); הדבר חשוב לערעור ולחלוקה בין מעוולים.'}, {'q': 'נהג רכב לא חגר חגורת בטיחות. רכב אחר פגע בו ברשלנות. הוכח שהחגורה הייתה מקטינה את פציעותיו (תביעה לפי הפקודה, לא לפי חוק הפיצויים). האם ניתן לייחס לו אשם תורם?', 'o': ['לא, כי אשם תורם חל רק על מי שגרם לתאונה', 'לא, כי הוא לא גרם לתאונה', 'כן — והתביעה נדחית כולה', 'כן — ניתן להפחית בגין התרשלות שתרמה להיקף הנזק'], 'c': 3, 'e': 'נכון. התרשלות שהגדילה את הנזק היא אשם תורם, וההפחתה נגזרת מהחלק שהאמצעי היה מונע.'}, {'q': 'האם ניתן לייחס אשם תורם לילד בן 9 שנפגע?', 'o': ['לא, כי ס׳ 9 פוטר ילד מתחת לגיל 12 מכל עניין נזיקי', 'כן, בדיוק כמו לבגיר', 'לא, כי ס׳ 5(ג) חל גם על אשם תורם', 'עקרונית כן, לפי ״הילד הסביר״ בגילו — אבל הפסיקה נזהרת מאוד'], 'c': 3, 'e': 'נכון. כך עולה מע״א 361/59 צוקרמן נ׳ שנברגר (ילד בן 10), והזהירות מודגמת בפרשת מרצלי.'}, {'q': 'ילד בן 8 הוזמן על ידי בעל מגרש לשחק בו, ונפגע ממתקן רעוע. בעל המגרש טוען שהילד שיחק באופן פרוע. מה ההוראה הרלוונטית?', 'o': ['ס׳ 69 — אשם תורם שגרם מוות', 'ס׳ 64(3) — ילד מתחת לגיל 12 שהוזמן או הורשה לשהות בנכס אינו נחשב כמי שגרם לנזק באשמו', 'ס׳ 66 — הגדלת הפיצויים', 'ס׳ 5(ב) — חובה חקוקה'], 'c': 1, 'e': 'נכון. ס׳ 64(3) שולל ייחוס אשם לילד שהמזיק הזמין או הרשה לשהות בנכס שבו נפגע.'}, {'q': 'אדם התגרה בשכנו וקילל אותו, והשכן, שאיבד שליטה, היכה אותו. לפי איזה סעיף רשאי בית המשפט להפחית את הפיצוי או לפטור את השכן?', 'o': ['ס׳ 69', 'ס׳ 66', 'ס׳ 4', 'ס׳ 65'], 'c': 3, 'e': 'נכון. ס׳ 65: כשהתנהגות התובע היא שהביאה לאשם הנתבע, בית המשפט רשאי לפטור או להקטין את הפיצויים.'}, {'q': 'מה קובע ס׳ 66 לפקודה?', 'o': ['שאשם תורם אינו חל על עובדים', 'שאם הנתבע הביא לאשמו של התובע, רשאי בית המשפט להגדיל את הפיצויים, עד לסכום שהיה משולם בלי אשם התובע', 'שאשם הורים מיוחס לילד', 'שתלויים אינם נפגעים מאשם המנוח'], 'c': 1, 'e': 'נכון. ס׳ 66 מאפשר לרכך את ההפחתה כשהתנהגות הנתבע היא שהולידה את אשם התובע.'}, {'q': 'אדם נהרג בתאונה שבה גם הוא התרשל (אשמו 30%). תלוייו תובעים לפי ס׳ 78. מה הדין?', 'o': ['הפיצויים יופחתו בשיעור יחסי, לפי ס׳ 69', 'הפיצויים יופחתו ב-50% בכל מקרה', 'הם מקבלים פיצוי מלא, כי הם לא התרשלו', 'התביעה נדחית'], 'c': 0, 'e': 'נכון. כפי שהעיזבון היה מקבל פיצוי מופחת, כך גם התלויים — בשיעור יחסי.'}, {'q': 'מטופל אובדני אושפז במחלקה סגורה, ובית החולים התחייב להשגיח עליו. בשל רשלנות בהשגחה הוא התאבד. בית החולים טוען לאשם תורם. מה הדין לפי הלכת הדסה נ׳ גלעד?', 'o': ['הטענה נדחית, כי טענת אשם תורם תרוקן מתוכן את ההתחייבות להגן על המטופל מפני עצמו', 'הטענה מתקבלת ב-50%', 'אשם תורם לעולם אינו חל על חולים', 'הטענה מתקבלת תמיד, כי התאבדות היא מעשה מכוון'], 'c': 0, 'e': 'נכון. כשבית החולים קיבל על עצמו את האחריות לחיי המטופל, הוא אינו יכול לטעון שהמטופל עצמו אשם.'}, {'q': 'מה נקבע ברע״א 2809/18 קסברי נ׳ רוזן לגבי תאונה דו-צדדית?', 'o': ['שאפשר להפריד בין אחריות צד לנזק חברו לבין אשמו התורם בנזקו שלו, ורמת הזהירות אינה בהכרח אחידה', 'שרק הנהג המהיר יותר אחראי', 'שבתאונה דו-צדדית אשם תורם אינו חל', 'שכל צד אחראי למחצית מכל הנזקים'], 'c': 0, 'e': 'נכון. התנהגות יכולה להקים אשם תורם בתביעת הצד עצמו בלי להקים אחריות כלפי הצד השני.'}, {'q': 'מה המקור הנורמטיבי לנטל הקטנת הנזק בדיני הנזיקין?', 'o': ['ס׳ 68 לפקודה', 'ס׳ 5 לפקודה', 'ס׳ 14 לחוק החוזים (תרופות) — שחל ישירות על עוולות', 'הפסיקה, בהשראת העיקרון הכללי של דיני החיובים'], 'c': 3, 'e': 'נכון. אין בפקודה הוראה מפורשת, והפסיקה (״הקודחים״ נתניה) אימצה את העיקרון.'}, {'q': 'ניזוק סירב לעבור ניתוח מסוכן בעל סיכויי הצלחה בינוניים, שהיה עשוי לשפר את מצבו. מה הדין?', 'o': ['הסירוב שולל את התביעה כולה', 'הסירוב הוא תמיד הפרה של הנטל, וכל הנכות לא תפוצה', 'הסירוב סביר בנסיבות, ולכן ככלל אינו הפרה של נטל הקטנת הנזק', 'הסירוב הוא אשם תורם שמפחית 50%'], 'c': 2, 'e': 'נכון. נבחנת סבירות הסירוב בעיני אדם סביר במצבו; הפסיקה מכבדת את זכותו של אדם שלא ליטול סיכון ניתוחי משמעותי (בן לב, אליהו נ׳ בורבה).'}, {'q': 'ניזוק הוציא הוצאות סבירות על טיפול שנועד להקטין את נזקו, אך הטיפול לא הצליח. האם יוחזרו לו ההוצאות?', 'o': ['לא, כי הטיפול לא הצליח', 'רק אם המזיק אישר מראש', 'רק מחצית', 'כן, כי הוצאות סבירות להקטנת הנזק מוחזרות גם אם המאמץ נכשל'], 'c': 3, 'e': 'נכון. כך גם ההיגיון של ס׳ 14(ב) לחוק התרופות, שהפסיקה מחילה בנזיקין.'}, {'q': 'במה שונה הקטנת הנזק מאשם תורם באופן ההפחתה?', 'o': ['אשם תורם — אחוז מכלל הנזק לפי מידת האשמה; הקטנת נזק — שלילת הפיצוי על הנזק המסוים שהיה נמנע', 'שתיהן שוללות את התביעה', 'אין הבדל', 'אשם תורם — שלילת נזק מסוים; הקטנת נזק — אחוז מהנזק'], 'c': 0, 'e': 'נכון. זו ההבחנה הקלאסית, אף שהגבול בין המוסדות מחייב הבחנה זהירה (רע״א 4756/16).'}, {'q': 'מה נקבע ברע״א 4756/16 פלוני נ׳ מדינת ישראל – משטרת ישראל, בעניין עצור שסירב לחתום על תנאי שחרור בערובה?', 'o': ['שסירוב לחתום על ערבות הוא אשם תורם מלא', 'שהמשטרה חסינה', 'שהעצור אינו נושא באשם תורם בהחלטת המעצר, והשאלה הרלוונטית היא אם היה עליו להקטין את הנזק', 'שעצור שלא כדין אינו זכאי לפיצוי'], 'c': 2, 'e': 'נכון. ביהמ״ש הבחין בין אשם תורם (שלא היה) לבין השאלה אם העצור צריך היה להקטין את הנזק בהסכמה לחתום על תנאי הערובה.'}, {'q': 'מה ההבדל המרכזי בין הסתכנות מרצון (ס׳ 5) לבין אשם תורם (ס׳ 68)?', 'o': ['הסתכנות מרצון היא הגנה מלאה ונבחנת בעיקר לפי ידיעה ורצון סובייקטיביים; אשם תורם מפחית לפי מבחן אובייקטיבי', 'אין הבדל', 'אשם תורם הוא הגנה מלאה; הסתכנות מרצון מפחיתה', 'הסתכנות מרצון חלה תמיד על הפרת חובה חקוקה'], 'c': 0, 'e': 'נכון. בשל התוצאה הקיצונית, הפסיקה מפרשת את ההסתכנות מרצון בצמצום ומעדיפה חלוקה דרך אשם תורם.'}, {'q': 'לפי ס׳ 68(א) סיפא, מה דין הגבלת חבות בחוזה כשיש אשם תורם?', 'o': ['האשם התורם אינו מכשיל הגנה הנובעת מחוזה, והתובע לא יקבל מעל הגבול שנקבע', 'היא בטלה', 'היא חלה רק על נזקי גוף', 'היא מוכפלת'], 'c': 0, 'e': 'נכון. זו לשון הסיפא: אשם תורם ״אין כוחו יפה להכשיל הגנה הנובעת מחוזה״, ותקרת חבות בחוזה או בדין נשמרת.'}, {'q': 'אשם תורם מעוגן ב:', 'o': ["ס' 35", "ס' 64", "ס' 68", "ס' 2"], 'c': 2, 'e': "ס' 68 לפקודה."}, {'q': 'תוצאת אשם תורם כיום:', 'o': ['שלילת פיצוי מלאה', 'הפחתה יחסית', 'אין השפעה', 'פיצוי כפול'], 'c': 1, 'e': 'חלוקת אחריות באחוזים.'}, {'q': 'לפי מה נקבע שיעור האשם התורם?', 'o': ['גובה הנזק', 'אשמה מוסרית ותרומה סיבתית', 'גיל', 'הכנסה'], 'c': 1, 'e': 'מידת האחריות של כל צד.'}, {'q': 'חובת הקטנת הנזק חלה:', 'o': ['על המזיק', 'על הניזוק', 'על ביהמ"ש', 'על המבטח'], 'c': 1, 'e': 'הניזוק חייב לפעול באמצעים סבירים.'}, {'q': 'אשם תורם נוגע להתנהגות הניזוק:', 'o': ['לאחר הנזק', 'בגרימת הנזק', 'בכתב', 'בהסכמה'], 'c': 1, 'e': 'הקטנת הנזק נוגעת ללאחריו.'}]
